package com.payments.consumer

import scala.collection.mutable
import scala.util.{Try, Success, Failure}
import java.util.concurrent.atomic.{AtomicInteger, AtomicLong}
import java.time.Instant

// Circuit breaker states
sealed trait CircuitState
case object Closed extends CircuitState
case object Open extends CircuitState
case object HalfOpen extends CircuitState

case class PaymentMessage(
  transactionId: String,
  amount: BigDecimal,
  currency: String,
  merchantId: String,
  customerId: String,
  idempotencyKey: String,
  retryCount: Int = 0
)

case class ProcessingResult(success: Boolean, transactionId: String, settled: BigDecimal)

class CircuitBreaker(failureThreshold: Int = 5, resetTimeoutMs: Long = 30000) {
  private val failureCount = new AtomicInteger(0)
  private val lastFailureTime = new AtomicLong(0)
  @volatile private var state: CircuitState = Closed

  def currentState: CircuitState = {
    if (state == Open && (System.currentTimeMillis() - lastFailureTime.get()) > resetTimeoutMs) {
      state = HalfOpen
    }
    state
  }

  def recordSuccess(): Unit = {
    failureCount.set(0)
    state = Closed
  }

  def recordFailure(): Unit = {
    val count = failureCount.incrementAndGet()
    lastFailureTime.set(System.currentTimeMillis())
    if (count >= failureThreshold) {
      state = Open
    }
  }

  def allowRequest: Boolean = currentState != Open
}

class PaymentLedger {
  private val processedPayments = mutable.Map[String, ProcessingResult]()
  private val pendingSettlements = mutable.ListBuffer[(String, BigDecimal)]()
  private val merchantBalances = mutable.Map[String, BigDecimal]().withDefaultValue(BigDecimal(0))

  def isProcessed(idempotencyKey: String): Option[ProcessingResult] = {
    processedPayments.get(idempotencyKey)
  }

  def recordProcessing(idempotencyKey: String, result: ProcessingResult): Unit = {
    processedPayments(idempotencyKey) = result
  }

  def addPendingSettlement(merchantId: String, amount: BigDecimal): Unit = {
    pendingSettlements += ((merchantId, amount))
  }

  def creditMerchant(merchantId: String, amount: BigDecimal): Unit = {
    merchantBalances(merchantId) = merchantBalances(merchantId) + amount
  }

  def getMerchantBalance(merchantId: String): BigDecimal = merchantBalances(merchantId)
  def getPendingCount: Int = pendingSettlements.size
}

class PaymentProcessor(ledger: PaymentLedger, circuitBreaker: CircuitBreaker) {

  private val deadLetterQueue = mutable.ListBuffer[PaymentMessage]()
  private val maxRetries = 3

  def processMessage(message: PaymentMessage): ProcessingResult = {
    // Idempotency check
    ledger.isProcessed(message.idempotencyKey) match {
      case Some(existingResult) => return existingResult
      case None => // continue processing
    }

    if (!circuitBreaker.allowRequest) {
      handleCircuitOpen(message)
      return ProcessingResult(false, message.transactionId, BigDecimal(0))
    }

    Try(executePayment(message)) match {
      case Success(result) =>
        circuitBreaker.recordSuccess()
        ledger.recordProcessing(message.idempotencyKey, result)
        result
      case Failure(ex) =>
        circuitBreaker.recordFailure()
        handleFailure(message, ex)
    }
  }

  private def executePayment(message: PaymentMessage): ProcessingResult = {
    validatePayment(message)
    val settledAmount = settlePayment(message)
    ProcessingResult(true, message.transactionId, settledAmount)
  }

  private def validatePayment(message: PaymentMessage): Unit = {
    require(message.amount > 0, "Amount must be positive")
    require(message.currency.length == 3, "Invalid currency code")
    require(message.merchantId.nonEmpty, "Merchant ID required")
  }

  private def settlePayment(message: PaymentMessage): BigDecimal = {
    val feeRate = calculateFeeRate(message.merchantId)
    val netAmount = message.amount * (BigDecimal(1) - feeRate)
    ledger.addPendingSettlement(message.merchantId, netAmount)
    ledger.creditMerchant(message.merchantId, netAmount)
    netAmount
  }

  private def calculateFeeRate(merchantId: String): BigDecimal = {
    // Tiered fee structure based on merchant classification
    merchantId.hashCode.abs % 3 match {
      case 0 => BigDecimal("0.029")  // Standard
      case 1 => BigDecimal("0.025")  // Preferred
      case 2 => BigDecimal("0.022")  // Premium
    }
  }

  private def handleCircuitOpen(message: PaymentMessage): Unit = {
    if (message.retryCount < maxRetries) {
      // Re-enqueue with incremented retry - settlement credited optimistically
      val retryMessage = message.copy(retryCount = message.retryCount + 1)
      val optimisticAmount = message.amount * (BigDecimal(1) - calculateFeeRate(message.merchantId))
      ledger.creditMerchant(message.merchantId, optimisticAmount)
      requeueMessage(retryMessage)
    } else {
      deadLetterQueue += message
    }
  }

  private def handleFailure(message: PaymentMessage, ex: Throwable): ProcessingResult = {
    if (message.retryCount < maxRetries) {
      val retryMessage = message.copy(retryCount = message.retryCount + 1)
      requeueMessage(retryMessage)
    } else {
      deadLetterQueue += message
    }
    ProcessingResult(false, message.transactionId, BigDecimal(0))
  }

  private def requeueMessage(message: PaymentMessage): Unit = {
    // Simulate re-enqueue to message broker
    // In production this would publish back to RabbitMQ/Kafka
    processMessage(message)
  }

  def getDeadLetterCount: Int = deadLetterQueue.size
}
